; ldai.asm -- chapter 8: the two loads that set flags
; generated by gen08.py
        INCLUDE "msx.inc"
        OUTPUT "ldai.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
; LD A,I and LD A,R, with $80 and $00 put in I or R, interrupts off and on,
; and F clear and set before each load. What F and A became goes into the
; RAM, two bytes a test. The frame interrupt comes first, so that no other
; comes in the middle and moves R on.
init:   di
        ld sp, SYS_AREA
        im 1
        ei
        halt                    ; the frame interrupt, and C-BIOS's routine
        ld a, $80
        ld i, a                 ; I = $80
        di                      ; interrupts off
        ld bc, $00
        push bc
        pop af                  ; F = $00
        ld a, i
        push af
        pop hl
        ld (RESULTS+0), hl      ; F, then A
        ld a, $80
        ld i, a                 ; I = $80
        di                      ; interrupts off
        ld bc, $FF
        push bc
        pop af                  ; F = $FF
        ld a, i
        push af
        pop hl
        ld (RESULTS+2), hl      ; F, then A
        ld a, $80
        ld i, a                 ; I = $80
        ei                      ; interrupts on
        ld bc, $00
        push bc
        pop af                  ; F = $00
        ld a, i
        push af
        pop hl
        ld (RESULTS+4), hl      ; F, then A
        ld a, $80
        ld i, a                 ; I = $80
        ei                      ; interrupts on
        ld bc, $FF
        push bc
        pop af                  ; F = $FF
        ld a, i
        push af
        pop hl
        ld (RESULTS+6), hl      ; F, then A
        ld a, $00
        ld i, a                 ; I = $00
        di                      ; interrupts off
        ld bc, $00
        push bc
        pop af                  ; F = $00
        ld a, i
        push af
        pop hl
        ld (RESULTS+8), hl      ; F, then A
        ld a, $00
        ld i, a                 ; I = $00
        di                      ; interrupts off
        ld bc, $FF
        push bc
        pop af                  ; F = $FF
        ld a, i
        push af
        pop hl
        ld (RESULTS+10), hl     ; F, then A
        ld a, $00
        ld i, a                 ; I = $00
        ei                      ; interrupts on
        ld bc, $00
        push bc
        pop af                  ; F = $00
        ld a, i
        push af
        pop hl
        ld (RESULTS+12), hl     ; F, then A
        ld a, $00
        ld i, a                 ; I = $00
        ei                      ; interrupts on
        ld bc, $FF
        push bc
        pop af                  ; F = $FF
        ld a, i
        push af
        pop hl
        ld (RESULTS+14), hl     ; F, then A
        ld a, $80
        ld r, a                 ; R = $80
        di                      ; interrupts off
        ld bc, $00
        push bc
        pop af                  ; F = $00
        ld a, r
        push af
        pop hl
        ld (RESULTS+16), hl     ; F, then A
        ld a, $80
        ld r, a                 ; R = $80
        di                      ; interrupts off
        ld bc, $FF
        push bc
        pop af                  ; F = $FF
        ld a, r
        push af
        pop hl
        ld (RESULTS+18), hl     ; F, then A
        ld a, $80
        ld r, a                 ; R = $80
        ei                      ; interrupts on
        ld bc, $00
        push bc
        pop af                  ; F = $00
        ld a, r
        push af
        pop hl
        ld (RESULTS+20), hl     ; F, then A
        ld a, $80
        ld r, a                 ; R = $80
        ei                      ; interrupts on
        ld bc, $FF
        push bc
        pop af                  ; F = $FF
        ld a, r
        push af
        pop hl
        ld (RESULTS+22), hl     ; F, then A
        ld a, $00
        ld r, a                 ; R = $00
        di                      ; interrupts off
        ld bc, $00
        push bc
        pop af                  ; F = $00
        ld a, r
        push af
        pop hl
        ld (RESULTS+24), hl     ; F, then A
        ld a, $00
        ld r, a                 ; R = $00
        di                      ; interrupts off
        ld bc, $FF
        push bc
        pop af                  ; F = $FF
        ld a, r
        push af
        pop hl
        ld (RESULTS+26), hl     ; F, then A
        ld a, $00
        ld r, a                 ; R = $00
        ei                      ; interrupts on
        ld bc, $00
        push bc
        pop af                  ; F = $00
        ld a, r
        push af
        pop hl
        ld (RESULTS+28), hl     ; F, then A
        ld a, $00
        ld r, a                 ; R = $00
        ei                      ; interrupts on
        ld bc, $FF
        push bc
        pop af                  ; F = $FF
        ld a, r
        push af
        pop hl
        ld (RESULTS+30), hl     ; F, then A
        di
        xor a
        ld i, a                 ; I as C-BIOS had it
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
